import json, sys
d = json.load(sys.stdin)
# Print the headline metrics table
if 'policy_scores' in d:
    print('=== Policy scores (first 10) ===')
    for row in d['policy_scores'][:10]:
        print(row)
elif 'tasks' in d:
    print(f'Tasks: {d[\"tasks\"]}')
# Try top-level keys
for k in sorted(d.keys()):
    v = d[k]
    if isinstance(v, (str, int, float, bool)):
        print(f'{k}: {v}')
    elif isinstance(v, list) and len(v) < 5:
        print(f'{k}: {v}')
" 2>/dev/null | head -30

python3 -c "
